func (s *server) handleConn(conn net.Conn) {
	defer conn.Close()

	r := bufio.NewReader(conn)
	w := bufio.NewWriter(conn)

	for {
		argv, err := readRequest(r)
		if err != nil {
			if errors.Is(err, io.EOF) {
				return
			}
			var pe protocolError
			if errors.As(err, &pe) {
				_ = writeError(w, "ERR "+pe.msg)
				_ = w.Flush()
			}
			return
		}

