type entry struct {
	value    []byte
	expireAt int64 // absolute unix time in milliseconds; 0 means no expiry
}

type database struct {
	mu   sync.Mutex
	data map[string]entry
}

func newDatabase() *database {
	return &database{data: make(map[string]entry)}
}

func nowMillis() int64 {
	return time.Now().UnixNano() / int64(time.Millisecond)
}

func (db *database) get(key []byte) ([]byte, bool) {
	ks := string(key)

	db.mu.Lock()
	defer db.mu.Unlock()
	now := nowMillis()

	e, ok := db.data[ks]
	if !ok {
		return nil, false
	}
	if e.expireAt > 0 && e.expireAt <= now {
		delete(db.data, ks)
		return nil, false
	}
	v := make([]byte, len(e.value))
	copy(v, e.value)
	return v, true
}

func (db *database) set(key, value []byte, expireAt int64) {
	ks := string(key)
	v := make([]byte, len(value))
	copy(v, value)

	db.mu.Lock()
	db.data[ks] = entry{value: v, expireAt: expireAt}
	db.mu.Unlock()
}

func (db *database) del(keys [][]byte) int64 {
	var deleted int64

	db.mu.Lock()
	defer db.mu.Unlock()
	now := nowMillis()

	for _, key := range keys {
		ks := string(key)
		e, ok := db.data[ks]
		if !ok {
			continue
		}
		if e.expireAt > 0 && e.expireAt <= now {
			delete(db.data, ks)
			continue
		}
		delete(db.data, ks)
		deleted++
	}
	return deleted
}

type server struct {
	db *database
